// Process Meta Ads data and format for Slack
const data = $input.first().json.data[0];

// Extract metrics
const spend = parseFloat(data.spend || 0);
const impressions = parseInt(data.impressions || 0);
const clicks = parseInt(data.clicks || 0);
const ctr = parseFloat(data.ctr || 0);
const cpc = parseFloat(data.cpc || 0);

// Find conversions from actions array
let conversions = 0;
let purchaseValue = 0;
if (data.actions) {
  const purchaseAction = data.actions.find(a => a.action_type === 'purchase');
  if (purchaseAction) conversions = parseInt(purchaseAction.value);
}

// Calculate CPA and ROAS
const cpa = conversions > 0 ? spend / conversions : 0;
const roas = data.purchase_roas ? parseFloat(data.purchase_roas[0].value) : 0;

// Format Slack message
const message = `📘 *Meta Ads Daily Report*\n${new Date().toLocaleDateString()}\n\n` +
  `💰 *Spend:* $${spend.toFixed(2)}\n` +
  `👁️ *Impressions:* ${impressions.toLocaleString()}\n` +
  `🖱️ *Clicks:* ${clicks.toLocaleString()}\n` +
  `📈 *CTR:* ${(ctr * 100).toFixed(2)}%\n` +
  `💵 *CPC:* $${cpc.toFixed(2)}\n` +
  `🎯 *Conversions:* ${conversions}\n` +
  `📊 *CPA:* $${cpa.toFixed(2)}\n` +
  `🔥 *ROAS:* ${roas.toFixed(2)}x`;

return [{json: {message, spend, conversions, cpa, roas}}];
